{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.AudioInputSchema",
  "description": "Schema for an audio input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the expected audio.",
      "type": [
        "string",
        "null"
      ]
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.ImageUrlDetail",
  "description": "Detail level for image processing.",
  "oneOf": [
    {
      "description": "Let the model decide the detail level.",
      "type": "string",
      "const": "auto"
    },
    {
      "description": "Low detail mode (faster, less tokens).",
      "type": "string",
      "const": "low"
    },
    {
      "description": "High detail mode (more accurate, more tokens).",
      "type": "string",
      "const": "high"
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.StringInputSchema",
  "description": "Schema for a string input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the string.",
      "type": [
        "string",
        "null"
      ]
    },
    "enum": {
      "description": "If provided, the string must be one of these values.",
      "type": [
        "array",
        "null"
      ],
      "items": {
        "type": "string"
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.Expression",
  "description": "An expression that can be either JMESPath or Starlark.\n\nSerializes as `{\"$jmespath\": \"...\"}` or `{\"$starlark\": \"...\"}` in JSON.\n\n# Examples\n\nJMESPath:\n```json\n{\"$jmespath\": \"input.items[0].name\"}\n```\n\nStarlark:\n```json\n{\"$starlark\": \"input['items'][0]['name']\"}\n```",
  "oneOf": [
    {
      "description": "A JMESPath expression.",
      "type": "object",
      "properties": {
        "JMESPath": {
          "type": "string"
        }
      },
      "required": [
        "JMESPath"
      ],
      "additionalProperties": false
    },
    {
      "description": "A Starlark expression.",
      "type": "object",
      "properties": {
        "Starlark": {
          "type": "string"
        }
      },
      "required": [
        "Starlark"
      ],
      "additionalProperties": false
    },
    {
      "description": "A predefined special expression variant.",
      "type": "object",
      "properties": {
        "Special": {
          "$ref": "functions.expression.Special"
        }
      },
      "required": [
        "Special"
      ],
      "additionalProperties": false
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.AudioInputSchema",
  "description": "Schema for an audio input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the expected audio.",
      "type": [
        "string",
        "null"
      ]
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.ObjectInputSchema",
  "description": "Schema for an object input with named properties.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the object.",
      "type": [
        "string",
        "null"
      ]
    },
    "properties": {
      "description": "Schema for each property in the object.",
      "type": "object",
      "additionalProperties": {
        "$ref": "functions.expression.InputSchema"
      }
    },
    "required": {
      "description": "List of property names that must be present.",
      "type": [
        "array",
        "null"
      ],
      "items": {
        "type": "string"
      }
    }
  },
  "required": [
    "properties"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.ArrayInputSchema",
  "description": "Schema for an array input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the array.",
      "type": [
        "string",
        "null"
      ]
    },
    "minItems": {
      "description": "Minimum number of items required.",
      "type": [
        "integer",
        "null"
      ],
      "format": "uint64",
      "minimum": 0
    },
    "maxItems": {
      "description": "Maximum number of items allowed.",
      "type": [
        "integer",
        "null"
      ],
      "format": "uint64",
      "minimum": 0
    },
    "items": {
      "description": "Schema for each item in the array.",
      "$ref": "functions.expression.InputSchema"
    }
  },
  "required": [
    "items"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.FileInputSchema",
  "description": "Schema for a file input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the expected file.",
      "type": [
        "string",
        "null"
      ]
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.AnyOfInputSchema",
  "description": "Schema for a union of possible types - input must match at least one.",
  "type": "object",
  "properties": {
    "anyOf": {
      "description": "The possible schemas that the input can match.",
      "type": "array",
      "items": {
        "$ref": "functions.expression.InputSchema"
      }
    }
  },
  "required": [
    "anyOf"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.InputAudio",
  "description": "Audio input for multimodal messages.",
  "type": "object",
  "properties": {
    "data": {
      "description": "Base64-encoded audio data.",
      "type": "string"
    },
    "format": {
      "description": "The audio format (e.g., \"wav\", \"mp3\").",
      "type": "string"
    }
  },
  "required": [
    "data",
    "format"
  ]
}
